function tkRenderNav(string $active,array $range): void { $items=['index.php'=>['overview','🏠 Tổng quan'],'doanh_thu.php'=>['revenue','💰 Doanh thu'],'don_hang.php'=>['orders','📦 Đơn hàng'],'san_pham.php'=>['products','📱 Sản phẩm'],'khach_hang.php'=>['customers','👥 Khách hàng']]; echo '<div class="tk-nav">'; foreach($items as $file=>$i){$cls=$active===$i[0]?'active':''; echo '<a class="'.$cls.'" href="'.h(tkPageUrl($file,$range)).'">'.$i[1].'</a>'; } echo '</div>'; }
function tkRenderFilter(array $range): void { ?>
<div class="tk-filter"><div class="tk-pills">
<?php foreach(['today'=>'Hôm nay','7days'=>'7 ngày','month'=>'Tháng này','year'=>'Năm nay'] as $k=>$v): ?><a class="<?= $range['preset']===$k?'active':'' ?>" href="?preset=<?= $k ?>"><?= $v ?></a><?php endforeach; ?>
</div><form method="get" class="tk-filter-row"><div><label class="form-label small fw-semibold">Từ ngày</label><input type="date" name="from" class="form-control" value="<?= h($range['from']) ?>"></div><div><label class="form-label small fw-semibold">Đến ngày</label><input type="date" name="to" class="form-control" value="<?= h($range['to']) ?>"></div><button class="btn btn-primary px-4">Lọc dữ liệu</button></form></div><?php }
function tkBadge(string $status): string { $label=tkStatusLabel($status); $s=mb_strtolower($label,'UTF-8'); if(str_contains($s,'hoàn thành')||str_contains($s,'đã giao'))$c='tk-ok'; elseif(str_contains($s,'hủy'))$c='tk-danger'; elseif(str_contains($s,'giao'))$c='tk-info'; elseif(str_contains($s,'duyệt')||str_contains($s,'xử lý'))$c='tk-warn'; else $c='tk-muted'; return '<span class="tk-badge '.$c.'">'.h($label).'</span>'; }
function tkRenderPagination(array $pager,array $range,string $param='page'): void {
    if(($pager['pages']??1)<=1) return; $page=(int)$pager['page']; $pages=(int)$pager['pages'];
    echo '<div class="tk-pagination">';
    if($page>1) echo '<a href="?'.h(tkQuery($range,[$param=>$page-1])).'">‹</a>'; else echo '<span class="disabled">‹</span>';
    $start=max(1,$page-2); $end=min($pages,$page+2);
    if($start>1){ echo '<a href="?'.h(tkQuery($range,[$param=>1])).'">1</a>'; if($start>2) echo '<span class="disabled">…</span>'; }
    for($i=$start;$i<=$end;$i++){ $cls=$i===$page?'active':''; echo '<a class="'.$cls.'" href="?'.h(tkQuery($range,[$param=>$i])).'">'.$i.'</a>'; }
    if($end<$pages){ if($end<$pages-1) echo '<span class="disabled">…</span>'; echo '<a href="?'.h(tkQuery($range,[$param=>$pages])).'">'.$pages.'</a>'; }
    if($page<$pages) echo '<a href="?'.h(tkQuery($range,[$param=>$page+1])).'">›</a>'; else echo '<span class="disabled">›</span>';
    echo '</div>';
}
